// The ONE canonical answer to "what are the current TradingView levels / alerts / setups?".
// Built only from database records with a fixed template (Stavros, 2026-10-12: "it should just pull
// right from db in the same format every time"). Grokbot relays `text` word for word; nothing here is
// generated by a model at request time.

import { fmtRR, getLeverageDesk } from "./desk";
import { getLimits, type LimitOrder } from "./limits";
import { supabaseAdmin } from "@/lib/supabase/admin";
import { livePrice, STALE_MIN } from "./livePrice";
import { getLiquidity, type Liquidity } from "./liquidity";

const n = (v: unknown, d = 2) =>
  v === null || v === undefined || v === "" || Number.isNaN(Number(v))
    ? "—"
    : Number(v).toLocaleString("en-US", { maximumFractionDigits: d });
const phx = (iso?: string | null) =>
  iso
    ? new Date(iso).toLocaleString("en-US", { timeZone: "America/Phoenix", weekday: "short", month: "short", day: "numeric", hour: "numeric", minute: "2-digit" })
    : "—";
const pct = (a: number, b: number) => `${((Math.abs(a - b) / b) * 100).toFixed(2)}%`;

export type LevelAlert = { alert_id: string; tv_alert_id: number | null; price: number | null; label: string; condition: string };
export type LevelCoin = {
  asset: string;
  limits: LimitOrder[];
  price: number | null;
  checkedAt: string | null;
  priceAt?: string | null;
  priceSource?: string;
  bias: string | null;
  htf: string | null;
  openTrade: null | { trade_id: string; direction: string; entry: number; stop: number | null; tp1: number | null; tp2: number | null; leverage: number | null };
  alerts: LevelAlert[];
  plays: { signal_id: string; direction: string; trigger: number | null; entry: number | null; stop: number | null; tp1: number | null; rr: number | null; score: number | null; grade: number | null; status: string; condition: string | null }[];
  rangeLow: number | null;
  rangeHigh: number | null;
  support: number[];
  resistance: number[];
};

// Red-folder day (CPI / FOMC / NFP), Phoenix date — written by the daily task into econ_days (Stavros, 2026-10-14).
export async function getEconDay(): Promise<{ day: string; red: boolean; events: string | null; known: boolean } | null> {
  const day = new Date().toLocaleDateString("en-CA", { timeZone: "America/Phoenix" });
  try {
    const { data } = await supabaseAdmin().from("econ_days").select("day, red, events").eq("day", day).maybeSingle();
    return data ? { day, red: !!data.red, events: data.events ?? null, known: true } : { day, red: false, events: null, known: false };
  } catch {
    return null;
  }
}

export async function buildLevels() {
  const [lev, lim, econ, openPlan] = await Promise.all([
    getLeverageDesk(),
    getLimits().catch(() => ({ open: [] as LimitOrder[] })),
    getEconDay(),
    (async () => {
      try {
        const day = new Date().toLocaleDateString("en-CA", { timeZone: "America/Phoenix" });
        const { data } = await supabaseAdmin().from("lev_open_plan").select("market_bias, confidence, headline, open_strategy").eq("plan_date", day).maybeSingle();
        return data as { market_bias: string | null; confidence: number | null; headline: string | null; open_strategy: string | null } | null;
      } catch {
        return null;
      }
    })(),
  ]);
  const mineLimits = lim.open.filter((o) => o.origin !== "paper");
  const now = new Date().toISOString();

  // Coins shown: core BTC/ETH, the Scout's in-play coins, and any coin with an open trade or a live alert.
  const coins = new Set<string>(["BTC", "ETH"]);
  lev.universe.filter((u) => u.in_play).forEach((u) => coins.add(u.asset));
  lev.openTrades.forEach((t) => coins.add(t.symbol));
  mineLimits.forEach((o) => coins.add(o.symbol));
  lev.alerts.filter((a) => a.status === "active" && a.tv_alert_id).forEach((a) => coins.add(a.asset));

  // LIVE prices (desk journal #9, 2026-10-19): the header used to print the last desk-check price (days old) as the price.
  const lives = new Map<string, { price: number; source: string; at: number } | null>(
    await Promise.all([...coins].map(async (c) => [c, await livePrice(c).catch(() => null)] as const)),
  );
  const liqs = new Map<string, Liquidity | null>(
    await Promise.all([...coins].map(async (c) => [c, await getLiquidity(c).catch(() => null)] as const)),
  );
  const out: LevelCoin[] = [...coins].map((asset) => {
    const h = lev.latest[asset];
    const t = lev.theses.find((x) => x.asset === asset);
    const lv = (h?.levels ?? t?.levels ?? {}) as { support?: number[]; resistance?: number[]; range_high?: number; range_low?: number };
    const lp = lives.get(asset) ?? null;
    const price = lp ? lp.price : h ? Number(h.price) : null;
    const tr = lev.openTrades.find((x) => x.symbol === asset);
    const entry = tr ? Number(tr.entry) : null;
    const alerts = lev.alerts
      .filter((a) => a.asset === asset && a.status === "active" && a.tv_alert_id)
      .map((a) => {
        const p = a.trigger_price == null ? null : Number(a.trigger_price);
        let label: string;
        const isLimit = p != null && mineLimits.some((o) => o.symbol === asset && Math.abs(Number(o.limit_price) - p) <= 0.0005 * p);
        if (isLimit) label = "LIMIT";
        else if (a.action === "EXIT" && tr && entry != null && p != null) {
          const isStop = tr.direction === "long" ? p < entry : p > entry;
          label = isStop ? "STOP" : "TARGET";
        } else if (a.action === "EXIT") label = "EXIT";
        else if (a.action === "ENTER") label = `LEVEL${a.direction && a.direction !== "neutral" ? ` · ${a.direction} play` : ""}`;
        else label = "NOTE";
        return { alert_id: a.alert_id, tv_alert_id: a.tv_alert_id, price: p, label, condition: a.condition };
      })
      .sort((x, y) => Number(y.price ?? 0) - Number(x.price ?? 0));
    const plays = lev.signals
      .filter((s) => s.asset === asset && ["watching", "armed", "triggered"].includes(s.status) && !s.outcome)
      .map((s) => ({
        signal_id: s.signal_id,
        direction: s.direction,
        trigger: s.trigger_price == null ? null : Number(s.trigger_price),
        entry: s.entry == null ? null : Number(s.entry),
        stop: s.stop == null ? null : Number(s.stop),
        tp1: s.tp1 == null ? null : Number(s.tp1),
        rr: s.rr_tp1 == null ? null : Number(s.rr_tp1),
        score: s.confidence_score == null ? null : Number(s.confidence_score),
        grade: s.confidence_grade == null ? null : Number(s.confidence_grade),
        status: s.status,
        condition: s.trigger_condition ?? null,
      }))
      .sort((x, y) => Number(y.trigger ?? y.entry ?? 0) - Number(x.trigger ?? x.entry ?? 0));
    const limits = mineLimits.filter((o) => o.symbol === asset);
    return {
      asset,
      limits,
      price,
      checkedAt: h?.ts ?? null,
      priceAt: lp ? new Date(lp.at).toISOString() : h?.ts ?? null,
      priceSource: lp ? lp.source : "desk check",
      bias: h?.bias ?? t?.bias ?? null,
      htf: h?.htf_bias ?? null,
      openTrade: tr
        ? {
            trade_id: tr.trade_id,
            direction: tr.direction,
            entry: Number(tr.entry),
            stop: tr.current_stop ?? tr.stop ?? null,
            tp1: tr.current_tp1 ?? tr.tp1 ?? tr.target ?? null,
            tp2: tr.current_tp2 ?? tr.tp2 ?? null,
            leverage: tr.leverage ?? null,
          }
        : null,
      alerts,
      plays,
      rangeLow: lv.range_low == null ? null : Number(lv.range_low),
      rangeHigh: lv.range_high == null ? null : Number(lv.range_high),
      support: (lv.support ?? []).map(Number).filter((x) => price == null || x < price).sort((a, b) => b - a).slice(0, 3),
      resistance: (lv.resistance ?? []).map(Number).filter((x) => price == null || x > price).sort((a, b) => a - b).slice(0, 3),
    };
  });

  // ------------------------------------------------------------ text — same layout every time
  const L: string[] = [];
  L.push(`MOONBAG LEVELS · ${phx(now)} Phoenix`);
  L.push("TradingView alerts and trade setups exactly as recorded in Moonbag.");
  if (openPlan) {
    L.push(`OPEN PLAN: ${(openPlan.market_bias ?? "neutral").toUpperCase()}${openPlan.confidence != null ? ` ${openPlan.confidence}%` : ""} — ${openPlan.headline ?? ""}`);
    if (openPlan.open_strategy) L.push(`At the open: ${openPlan.open_strategy}`);
  }
  L.push(
    econ?.red
      ? `RED-FOLDER DAY (${econ.events ?? "CPI / FOMC / NFP"}): A+ full risk, every other grade HALF risk; no new entry within 2h of the release.`
      : econ?.known
        ? `Today: no red-folder data${econ.events ? ` (${econ.events})` : ""} — normal risk.`
        : "Today: calendar not checked yet — check for CPI / FOMC / NFP before sizing.",
  );
  for (const c of out) {
    L.push("");
    const ageMin = c.priceAt ? Math.round((Date.now() - Date.parse(c.priceAt)) / 60_000) : null;
    const stale = ageMin == null || ageMin > STALE_MIN;
    L.push(`${c.asset}  ${n(c.price)} (${c.priceSource ?? "desk check"} ${phx(c.priceAt ?? c.checkedAt)}${stale ? ` — STALE${ageMin != null ? ` ${ageMin} min old` : ""}, check BloFin before trading` : ""}) · desk check ${phx(c.checkedAt)} · bias ${(c.bias ?? "—").toUpperCase()}${c.htf ? ` · 4h ${c.htf}` : ""}`);
    { const lq = liqs.get(c.asset); if (lq) L.push(`  ${lq.text}`); }
    if (c.openTrade) {
      const o = c.openTrade;
      const s = o.stop == null ? null : Number(o.stop);
      const t1 = o.tp1 == null ? null : Number(o.tp1);
      const rr = s != null && t1 != null && o.entry !== s ? Math.abs(t1 - o.entry) / Math.abs(o.entry - s) : null;
      L.push(`  OPEN TRADE  ${o.direction.toUpperCase()} @ ${n(o.entry)} · SL ${n(s)}${s != null ? ` (${pct(s, o.entry)})` : ""} · TP1 ${n(t1)}${rr != null ? ` (${fmtRR(rr)})` : ""}${o.tp2 != null ? ` · TP2 ${n(o.tp2)}` : ""}${o.leverage != null ? ` · ${n(o.leverage, 0)}x` : ""}`);
    } else {
      L.push("  OPEN TRADE  none");
    }
    L.push(
      `  TV ALERTS (${c.alerts.length})  ${
        c.alerts.length ? c.alerts.map((a) => `${a.condition.includes("down") ? "▼" : a.condition.includes("up") ? "▲" : "◆"} ${n(a.price)} ${a.label}`).join(" · ") : "none set"
      }`,
    );
    for (const o of c.limits) {
      L.push(`  OPEN LIMIT  ${o.direction === "long" ? "BUY" : "SELL"} ${n(o.limit_price, 6)}${o.quantity != null ? ` × ${n(o.quantity, 6)}` : ""} · SL ${n(o.current_stop ?? o.stop, 6)} · TP1 ${n(o.tp1, 6)}${o.plan_r != null ? ` (${fmtRR(Number(o.plan_r))})` : ""}${o.status === "touched" ? " · TOUCHED" : ""}`);
      if ((o as LimitOrder).invalid_if) L.push(`    INVALID IF → CANCEL: ${(o as LimitOrder).invalid_if}`);
    }
    if (c.plays.length) {
      for (const p of c.plays) {
        const lvl = p.trigger ?? p.entry;
        L.push(
          `  SETUP  ${p.direction.toUpperCase()} at ${n(lvl)}${p.condition ? ` if ${p.condition}` : ""} · entry ${n(p.entry)} · SL ${n(p.stop)}${p.stop != null && p.entry != null ? ` (${pct(p.stop, p.entry)})` : ""} · TP1 ${n(p.tp1)} · ${fmtRR(p.rr)} · score ${n(p.score, 0)}${p.grade != null ? ` (grade ${p.grade})` : ""} · ${p.status}`,
        );
      }
    } else {
      L.push("  SETUP  none set");
    }
    L.push(
      `  RANGE  ${n(c.rangeLow)} – ${n(c.rangeHigh)} · resistance ${c.resistance.length ? c.resistance.map((x) => n(x)).join(", ") : "—"} · support ${c.support.length ? c.support.map((x) => n(x)).join(", ") : "—"}`,
    );
  }
  L.push("");
  L.push("Source: Moonbag database. Not financial advice. Stavros places every BloFin order.");

  return { generated_at: now, econ, text: L.join("\n"), coins: out };
}
